create table public.works(id bigint generated by default as identity primary key,title text not null,type text default 'مانهوا',genre text default '',status text default 'در حال انتشار',chapters integer default 0,description text default '',cover text,created_at timestamptz default now());
alter table public.works enable row level security;
create policy "Public can read works" on public.works for select using(true);
-- Before production, create an admin role and restrict all write policies to admins only.
create table public.chapters(id bigint generated by default as identity primary key,work_id bigint references public.works(id) on delete cascade,chapter_number numeric not null,title text default '',created_at timestamptz default now());
alter table public.chapters enable row level security;
create policy "Public can read chapters" on public.chapters for select using(true);
create table public.bookmarks(user_id uuid references auth.users(id) on delete cascade,work_id bigint references public.works(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,work_id));
alter table public.bookmarks enable row level security;
create policy "Users manage own bookmarks" on public.bookmarks for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
